public struct Esse3CheckLoginResult: Codable, Hashable, Sendable {
    /// indica se la verifica delle credenziali ha avuto successp
    public var ok: Bool?
    /// indica se l'utente deve cambiare la password (ad esempio perché scaduta)
    public var changePassword: Bool?

    public init(
        ok: Bool? = nil,
        changePassword: Bool? = nil
    ) {
        self.ok = ok
        self.changePassword = changePassword
    }

    private enum CodingKeys: String, CodingKey {
        case ok = "ok"
        case changePassword = "changePassword"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.ok = container.decodeLenient(Bool.self, forKey: .ok)
        self.changePassword = container.decodeLenient(Bool.self, forKey: .changePassword)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(ok, forKey: .ok)
        try container.encode(changePassword, forKey: .changePassword)
    }
}

public struct Esse3CacheInfo: Codable, Hashable, Sendable {
    /// indica se ablitare (1)  o disabilitare (0) la cache http tramite gli header sulla response
    public var httpCacheEnable: Int
    /// indica se ablitare (1)  o disabilitare (0) la cache lato server
    public var serverCacheEnable: Int

    public init(
        httpCacheEnable: Int = 0,
        serverCacheEnable: Int = 0
    ) {
        self.httpCacheEnable = httpCacheEnable
        self.serverCacheEnable = serverCacheEnable
    }

    private enum CodingKeys: String, CodingKey {
        case httpCacheEnable = "httpCacheEnable"
        case serverCacheEnable = "serverCacheEnable"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.httpCacheEnable = container.decodeLenient(Int.self, forKey: .httpCacheEnable) ?? 0
        self.serverCacheEnable = container.decodeLenient(Int.self, forKey: .serverCacheEnable) ?? 0
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(httpCacheEnable, forKey: .httpCacheEnable)
        try container.encode(serverCacheEnable, forKey: .serverCacheEnable)
    }
}

public struct Esse3JWTModel: Codable, Hashable, Sendable {
    /// jwt
